45	/**
46	 * This class starts and runs external SPS service.
47	 */
48	@InterfaceAudience.Private
49	public final class ExternalStoragePolicySatisfier {
50	  public static final Logger LOG = LoggerFactory
51	      .getLogger(ExternalStoragePolicySatisfier.class);
52	
53	  private ExternalStoragePolicySatisfier() {
54	    // This is just a class to start and run external sps.
55	  }
56	
57	  /**
58	   * Main method to start SPS service.
59	   */
60	  public static void main(String[] args) throws Exception {
61	    NameNodeConnector nnc = null;
62	    try {
63	      StringUtils.startupShutdownMessage(StoragePolicySatisfier.class, args,
64	          LOG);
65	      HdfsConfiguration spsConf = new HdfsConfiguration();
66	      // login with SPS keytab
67	      secureLogin(spsConf);
68	      StoragePolicySatisfier sps = new StoragePolicySatisfier(spsConf);
69	      nnc = getNameNodeConnector(spsConf);
70	
71	      ExternalSPSContext context = new ExternalSPSContext(sps, nnc);
72	      sps.init(context);
73	      sps.start(StoragePolicySatisfierMode.EXTERNAL);
74	      if (sps != null) {
75	        sps.join();
76	      }
77	    } catch (Throwable e) {
78	      LOG.error("Failed to start storage policy satisfier.", e);
79	      terminate(1, e);
80	    } finally {
81	      if (nnc != null) {
82	        nnc.close();
83	      }
84	    }
85	  }
86	
87	  private static void secureLogin(Configuration conf)
88	      throws IOException {
89	    UserGroupInformation.setConfiguration(conf);
90	    String addr = conf.get(DFSConfigKeys.DFS_SPS_ADDRESS_KEY,
91	        DFSConfigKeys.DFS_SPS_ADDRESS_DEFAULT);
92	    InetSocketAddress socAddr = NetUtils.createSocketAddr(addr, 0,
93	        DFSConfigKeys.DFS_SPS_ADDRESS_KEY);
94	    SecurityUtil.login(conf, DFSConfigKeys.DFS_SPS_KEYTAB_FILE_KEY,
95	        DFSConfigKeys.DFS_SPS_KERBEROS_PRINCIPAL_KEY,
96	        socAddr.getHostName());
97	  }
98	
99	  private static NameNodeConnector getNameNodeConnector(Configuration conf)
100	      throws IOException, InterruptedException {
101	    final Collection<URI> namenodes = DFSUtil.getInternalNsRpcUris(conf);
102	    final Path externalSPSPathId = HdfsServerConstants.MOVER_ID_PATH;
103	    while (true) {
104	      try {
105	        final List<NameNodeConnector> nncs = NameNodeConnector
106	            .newNameNodeConnectors(namenodes,
107	                ExternalStoragePolicySatisfier.class.getSimpleName(),
108	                externalSPSPathId, conf,
109	                NameNodeConnector.DEFAULT_MAX_IDLE_ITERATIONS);
110	        return nncs.get(0);
111	      } catch (IOException e) {
112	        LOG.warn("Failed to connect with namenode", e);
113	        Thread.sleep(3000); // retry the connection after few secs
114	      }
115	    }
116	  }
117	}
