48	/**
49	 * A monitor class for checking whether block storage movements attempt
50	 * completed or not. If this receives block storage movement attempt
51	 * status(either success or failure) from DN then it will just remove the
52	 * entries from tracking. If there is no DN reports about movement attempt
53	 * finished for a longer time period, then such items will retries automatically
54	 * after timeout. The default timeout would be 5 minutes.
55	 */
56	public class BlockStorageMovementAttemptedItems {
57	  private static final Logger LOG =
58	      LoggerFactory.getLogger(BlockStorageMovementAttemptedItems.class);
59	
60	  /**
61	   * A map holds the items which are already taken for blocks movements
62	   * processing and sent to DNs.
63	   */
64	  private final List<AttemptedItemInfo> storageMovementAttemptedItems;
65	  private Map<Block, Set<StorageTypeNodePair>> scheduledBlkLocs;
66	  // Maintains separate Queue to keep the movement finished blocks. This Q
67	  // is used to update the storageMovementAttemptedItems list asynchronously.
68	  private final BlockingQueue<Block> movementFinishedBlocks;
69	  private volatile boolean monitorRunning = true;
70	  private Daemon timerThread = null;
71	  private final Context context;
72	  //
73	  // It might take anywhere between 5 to 10 minutes before
74	  // a request is timed out.
75	  //
76	  private long selfRetryTimeout = 5 * 60 * 1000;
77	
78	  //
79	  // It might take anywhere between 1 to 2 minutes before
80	  // a request is timed out.
81	  //
82	  private long minCheckTimeout = 1 * 60 * 1000; // minimum value
83	  private BlockStorageMovementNeeded blockStorageMovementNeeded;
84	  private final SPSService service;
85	
86	  public BlockStorageMovementAttemptedItems(SPSService service,
87	      BlockStorageMovementNeeded unsatisfiedStorageMovementFiles,
88	      Context context) {
89	    this.service = service;
90	    long recheckTimeout = this.service.getConf().getLong(
91	        DFS_STORAGE_POLICY_SATISFIER_RECHECK_TIMEOUT_MILLIS_KEY,
92	        DFS_STORAGE_POLICY_SATISFIER_RECHECK_TIMEOUT_MILLIS_DEFAULT);
93	    if (recheckTimeout > 0) {
94	      this.minCheckTimeout = Math.min(minCheckTimeout, recheckTimeout);
95	    }
96	
97	    this.selfRetryTimeout = this.service.getConf().getLong(
98	        DFS_STORAGE_POLICY_SATISFIER_SELF_RETRY_TIMEOUT_MILLIS_KEY,
99	        DFS_STORAGE_POLICY_SATISFIER_SELF_RETRY_TIMEOUT_MILLIS_DEFAULT);
100	    this.blockStorageMovementNeeded = unsatisfiedStorageMovementFiles;
101	    storageMovementAttemptedItems = new ArrayList<>();
102	    scheduledBlkLocs = new HashMap<>();
103	    movementFinishedBlocks = new LinkedBlockingQueue<>();
104	    this.context = context;
105	  }
106	
107	  /**
108	   * Add item to block storage movement attempted items map which holds the
109	   * tracking/blockCollection id versus time stamp.
110	   *
111	   * @param startPathId
112	   *          - start satisfier path identifier
113	   * @param fileId
114	   *          - file identifier
115	   * @param monotonicNow
116	   *          - time now
117	   * @param assignedBlocks
118	   *          - assigned blocks for block movement
119	   * @param retryCount
120	   *          - retry count
121	   */
122	  public void add(long startPathId, long fileId, long monotonicNow,
123	      Map<Block, Set<StorageTypeNodePair>> assignedBlocks, int retryCount) {
124	    AttemptedItemInfo itemInfo = new AttemptedItemInfo(startPathId, fileId,
125	        monotonicNow, assignedBlocks.keySet(), retryCount);
126	    synchronized (storageMovementAttemptedItems) {
127	      storageMovementAttemptedItems.add(itemInfo);
128	    }
129	    synchronized (scheduledBlkLocs) {
130	      scheduledBlkLocs.putAll(assignedBlocks);
131	    }
132	  }
133	
134	  /**
135	   * Notify the storage movement attempt finished block.
136	   *
137	   * @param reportedDn
138	   *          reported datanode
139	   * @param type
140	   *          storage type
141	   * @param reportedBlock
142	   *          reported block
143	   */
144	  public void notifyReportedBlock(DatanodeInfo reportedDn, StorageType type,
145	      Block reportedBlock) {
146	    synchronized (scheduledBlkLocs) {
147	      if (scheduledBlkLocs.size() <= 0) {
148	        return;
149	      }
150	      matchesReportedBlock(reportedDn, type, reportedBlock);
151	    }
152	  }
153	
154	  private void matchesReportedBlock(DatanodeInfo reportedDn, StorageType type,
155	      Block reportedBlock) {
156	    Set<StorageTypeNodePair> blkLocs = scheduledBlkLocs.get(reportedBlock);
157	    if (blkLocs == null) {
158	      return; // unknown block, simply skip.
159	    }
160	
161	    for (StorageTypeNodePair dn : blkLocs) {
162	      boolean foundDn = dn.getDatanodeInfo().compareTo(reportedDn) == 0 ? true
163	          : false;
164	      boolean foundType = dn.getStorageType().equals(type);
165	      if (foundDn && foundType) {
166	        blkLocs.remove(dn);
167	        Block[] mFinishedBlocks = new Block[1];
168	        mFinishedBlocks[0] = reportedBlock;
169	        context.notifyMovementTriedBlocks(mFinishedBlocks);
170	        // All the block locations has reported.
171	        if (blkLocs.size() <= 0) {
172	          movementFinishedBlocks.add(reportedBlock);
173	          scheduledBlkLocs.remove(reportedBlock); // clean-up reported block
174	        }
175	        return; // found
176	      }
177	    }
178	    if (LOG.isDebugEnabled()) {
179	      LOG.debug("Reported block:{} not found in attempted blocks. Datanode:{}"
180	          + ", StorageType:{}", reportedBlock, reportedDn, type);
181	    }
182	  }
183	
184	  /**
185	   * Starts the monitor thread.
186	   */
187	  public synchronized void start() {
188	    monitorRunning = true;
189	    timerThread = new Daemon(new BlocksStorageMovementAttemptMonitor());
190	    timerThread.setName("BlocksStorageMovementAttemptMonitor");
191	    timerThread.start();
192	  }
193	
194	  /**
195	   * Sets running flag to false. Also, this will interrupt monitor thread and
196	   * clear all the queued up tasks.
197	   */
198	  public synchronized void stop() {
199	    monitorRunning = false;
200	    if (timerThread != null) {
201	      timerThread.interrupt();
202	    }
203	    this.clearQueues();
204	  }
205	
206	  /**
207	   * Timed wait to stop monitor thread.
208	   */
209	  synchronized void stopGracefully() {
210	    if (timerThread == null) {
211	      return;
212	    }
213	    if (monitorRunning) {
214	      stop();
215	    }
216	    try {
217	      timerThread.join(3000);
218	    } catch (InterruptedException ie) {
219	    }
220	  }
221	
222	  /**
223	   * A monitor class for checking block storage movement attempt status and long
224	   * waiting items periodically.
225	   */
226	  private class BlocksStorageMovementAttemptMonitor implements Runnable {
227	    @Override
228	    public void run() {
229	      while (monitorRunning) {
230	        try {
231	          blockStorageMovementReportedItemsCheck();
232	          blocksStorageMovementUnReportedItemsCheck();
233	          Thread.sleep(minCheckTimeout);
234	        } catch (InterruptedException ie) {
235	          LOG.info("BlocksStorageMovementAttemptMonitor thread "
236	              + "is interrupted.", ie);
237	        } catch (IOException ie) {
238	          LOG.warn("BlocksStorageMovementAttemptMonitor thread "
239	              + "received exception and exiting.", ie);
240	        }
241	      }
242	    }
243	  }
244	
245	  @VisibleForTesting
246	  void blocksStorageMovementUnReportedItemsCheck() {
247	    synchronized (storageMovementAttemptedItems) {
248	      Iterator<AttemptedItemInfo> iter = storageMovementAttemptedItems
249	          .iterator();
250	      long now = monotonicNow();
251	      while (iter.hasNext()) {
252	        AttemptedItemInfo itemInfo = iter.next();
253	        if (now > itemInfo.getLastAttemptedOrReportedTime()
254	            + selfRetryTimeout) {
255	          long file = itemInfo.getFile();
256	          ItemInfo candidate = new ItemInfo(itemInfo.getStartPath(), file,
257	              itemInfo.getRetryCount() + 1);
258	          blockStorageMovementNeeded.add(candidate);
259	          iter.remove();
260	          LOG.info("TrackID: {} becomes timed out and moved to needed "
261	              + "retries queue for next iteration.", file);
262	        }
263	      }
264	    }
265	  }
266	
267	  @VisibleForTesting
268	  void blockStorageMovementReportedItemsCheck() throws IOException {
269	    // Removes all available blocks from this queue and process it.
270	    Collection<Block> finishedBlks = new ArrayList<>();
271	    movementFinishedBlocks.drainTo(finishedBlks);
272	
273	    // Update attempted items list
274	    for (Block blk : finishedBlks) {
275	      synchronized (storageMovementAttemptedItems) {
276	        Iterator<AttemptedItemInfo> iterator = storageMovementAttemptedItems
277	            .iterator();
278	        while (iterator.hasNext()) {
279	          AttemptedItemInfo attemptedItemInfo = iterator.next();
280	          attemptedItemInfo.getBlocks().remove(blk);
281	          if (attemptedItemInfo.getBlocks().isEmpty()) {
282	            blockStorageMovementNeeded.add(new ItemInfo(
283	                attemptedItemInfo.getStartPath(), attemptedItemInfo.getFile(),
284	                attemptedItemInfo.getRetryCount() + 1));
285	            iterator.remove();
286	          }
287	        }
288	      }
289	    }
290	  }
291	
292	  @VisibleForTesting
293	  public int getMovementFinishedBlocksCount() {
294	    return movementFinishedBlocks.size();
295	  }
296	
297	  @VisibleForTesting
298	  public int getAttemptedItemsCount() {
299	    synchronized (storageMovementAttemptedItems) {
300	      return storageMovementAttemptedItems.size();
301	    }
302	  }
303	
304	  public void clearQueues() {
305	    movementFinishedBlocks.clear();
306	    synchronized (storageMovementAttemptedItems) {
307	      storageMovementAttemptedItems.clear();
308	    }
309	    synchronized (scheduledBlkLocs) {
310	      scheduledBlkLocs.clear();
311	    }
312	  }
313	}
